namespace Umbraco.Cms.Web.UI.Custom.OpenIddictKeys;

public class CertificateOpenIddictServerCredentialsProvider : IOpenIddictServerCredentialsProvider
{
    private readonly X509Certificate2 _signingCertificate;
    private readonly X509Certificate2 _encryptionCertificate;

    public CertificateOpenIddictServerCredentialsProvider(string folder, string password)
    {
        _signingCertificate = X509CertificateLoader.LoadPkcs12FromFile(Path.Combine(folder, "signing.pfx"), password);
        _encryptionCertificate = X509CertificateLoader.LoadPkcs12FromFile(Path.Combine(folder, "encryption.pfx"), password);
