// Replaces the default provider when LBTEST_CERTS points at the certificate folder.
public class CertificateCredentialsComposer : IComposer
{
    public void Compose(IUmbracoBuilder builder)
    {
        var folder = Environment.GetEnvironmentVariable("LBTEST_CERTS");
        if (string.IsNullOrEmpty(folder))
        {
            return;
        }

        var password = Environment.GetEnvironmentVariable("LBTEST_CERT_PASSWORD") ?? string.Empty;
        builder.Services.AddUnique<IOpenIddictServerCredentialsProvider>(new CertificateOpenIddictServerCredentialsProvider(folder, password));
    }
}

